-- 131: a Backend Development path (owner decision, 22 Oct 2026).
--
-- WHY. A student aiming at Backend Developer was placed on Data Science (no backend path existed), so
-- their completed backend roadmap tasks never counted as proof on their path ("0 proved" next to 3 done).
-- NOW. Track 'backend' with 16 topics / 80 steps from content/syllabus/backend.json (written by hand, not
-- by a model). Only the seed rows and their step lists: each lesson is written once, later, by the course
-- builder, exactly like the 41 existing paths. Topic skills (Node.js, Express, REST APIs, SQL,
-- Authentication...) are what suggest_tracks matches against resume skills. Nothing existing changes.
-- Rollback: migration/131-rollback-backend-path.sql
begin;
insert into public.level_tracks (slug, name, emoji, interest, role, sort_order)
select 'backend', 'Backend Development', '🛠️', 'coding', 'Backend developer', coalesce(max(sort_order), 0) + 1 from public.level_tracks
on conflict (slug) do nothing;
with s as (insert into public.levels (track_slug, level_number, sub_level, kind, skill, title) values ('backend', 1, 1, 'explanation', 'Backend', 'How a Backend Works') on conflict do nothing returning id) insert into public.level_syllabus (level_id, why, steps) select id, 'Every app you use talks to a server; you need to know what that server does before you build one.', '["Client, Server and the Request-Response Cycle", "What Happens When You Type a URL", "Frontend vs Backend vs Database", "Ports, Hosts and localhost", "Reading a Server Log"]'::jsonb from s;
with s as (insert into public.levels (track_slug, level_number, sub_level, kind, skill, title) values ('backend', 2, 1, 'explanation', 'HTTP', 'HTTP for Backend Developers') on conflict do nothing returning id) insert into public.level_syllabus (level_id, why, steps) select id, 'HTTP is the language your server speaks all day.', '["HTTP Methods: GET, POST, PUT, PATCH, DELETE", "Status Codes That Matter: 200, 201, 400, 401, 403, 404, 500", "Headers, Body and Content-Type", "Query Parameters vs Path Parameters", "Cookies and Why HTTP Is Stateless"]'::jsonb from s;
with s as (insert into public.levels (track_slug, level_number, sub_level, kind, skill, title) values ('backend', 3, 1, 'explanation', 'Node.js', 'Node.js Foundations') on conflict do nothing returning id) insert into public.level_syllabus (level_id, why, steps) select id, 'Node.js lets you write servers in JavaScript, the language you already know from the web.', '["Running JavaScript Outside the Browser", "Modules: require and import", "npm and package.json", "The Event Loop in Plain Words", "Async Code: Callbacks, Promises and async/await", "Reading Environment Variables"]'::jsonb from s;
with s as (insert into public.levels (track_slug, level_number, sub_level, kind, skill, title) values ('backend', 4, 1, 'explanation', 'Express', 'Your First API with Express') on conflict do nothing returning id) insert into public.level_syllabus (level_id, why, steps) select id, 'Express is the most common way to turn Node.js into a web server.', '["Creating an Express App and a First Route", "Route Parameters and Query Strings", "Reading a JSON Request Body", "Sending JSON Responses with the Right Status", "Middleware: What Runs Before Your Route", "Organising Routes into Routers"]'::jsonb from s;
with s as (insert into public.levels (track_slug, level_number, sub_level, kind, skill, title) values ('backend', 5, 1, 'explanation', 'REST APIs', 'Designing a REST API') on conflict do nothing returning id) insert into public.level_syllabus (level_id, why, steps) select id, 'A clean API is easy for a frontend or another team to use without asking you.', '["Resources and URL Naming", "CRUD Mapped to HTTP Methods", "Consistent Error Responses", "Pagination, Filtering and Sorting", "Versioning an API"]'::jsonb from s;
with s as (insert into public.levels (track_slug, level_number, sub_level, kind, skill, title) values ('backend', 6, 1, 'explanation', 'Backend', 'Validating Input') on conflict do nothing returning id) insert into public.level_syllabus (level_id, why, steps) select id, 'Most backend bugs and attacks start with input you did not check.', '["Never Trust the Client", "Required Fields, Types and Lengths", "Validation with a Schema Library", "Returning Helpful 400 Errors"]'::jsonb from s;
with s as (insert into public.levels (track_slug, level_number, sub_level, kind, skill, title) values ('backend', 7, 1, 'explanation', 'SQL', 'Databases for Backend Developers') on conflict do nothing returning id) insert into public.level_syllabus (level_id, why, steps) select id, 'Your server''s job is mostly to save and read data safely.', '["Tables, Rows and Primary Keys", "Relationships and Foreign Keys", "Writing SELECT, INSERT, UPDATE, DELETE", "JOINs for Related Data", "Indexes and Why Queries Get Slow", "Transactions: All or Nothing"]'::jsonb from s;
with s as (insert into public.levels (track_slug, level_number, sub_level, kind, skill, title) values ('backend', 8, 1, 'explanation', 'SQL', 'Connecting Your API to a Database') on conflict do nothing returning id) insert into public.level_syllabus (level_id, why, steps) select id, 'This is where a backend becomes a real product.', '["Database Drivers and Connection Pools", "Parameterised Queries and SQL Injection", "Using an ORM or Query Builder", "Migrations: Changing the Schema Safely", "SQL vs NoSQL: When to Use Which"]'::jsonb from s;
with s as (insert into public.levels (track_slug, level_number, sub_level, kind, skill, title) values ('backend', 9, 1, 'explanation', 'Authentication', 'Authentication') on conflict do nothing returning id) insert into public.level_syllabus (level_id, why, steps) select id, 'Almost every app needs to know who is calling it.', '["Authentication vs Authorization", "Storing Passwords with Hashing", "Sessions and Cookies", "Tokens and JWT in Plain Words", "Protecting a Route", "Roles and Permissions"]'::jsonb from s;
with s as (insert into public.levels (track_slug, level_number, sub_level, kind, skill, title) values ('backend', 10, 1, 'explanation', 'Cybersecurity', 'Backend Security Basics') on conflict do nothing returning id) insert into public.level_syllabus (level_id, why, steps) select id, 'One security mistake can leak every user''s data.', '["The OWASP Top 10 for Backends", "Keeping Secrets Out of Code", "CORS Explained", "Rate Limiting", "HTTPS and Why It Matters"]'::jsonb from s;
with s as (insert into public.levels (track_slug, level_number, sub_level, kind, skill, title) values ('backend', 11, 1, 'explanation', 'Backend', 'Errors, Logging and Debugging') on conflict do nothing returning id) insert into public.level_syllabus (level_id, why, steps) select id, 'When something breaks at night, good logs tell you why in minutes.', '["Handling Errors in One Place", "Writing Useful Log Lines", "Request IDs and Tracing a Request", "Debugging a Failing Endpoint Step by Step"]'::jsonb from s;
with s as (insert into public.levels (track_slug, level_number, sub_level, kind, skill, title) values ('backend', 12, 1, 'explanation', 'Testing', 'Testing a Backend') on conflict do nothing returning id) insert into public.level_syllabus (level_id, why, steps) select id, 'Tests let you change code without fear of breaking it.', '["Unit Tests for Business Logic", "Testing an API Endpoint", "Test Data and a Test Database", "Mocking an Outside Service"]'::jsonb from s;
with s as (insert into public.levels (track_slug, level_number, sub_level, kind, skill, title) values ('backend', 13, 1, 'explanation', 'Redis', 'Performance and Caching') on conflict do nothing returning id) insert into public.level_syllabus (level_id, why, steps) select id, 'A slow API loses users; caching is the first tool to reach for.', '["Measuring Response Time", "The N+1 Query Problem", "In-Memory Caching", "Redis as a Cache", "When a Cache Goes Stale"]'::jsonb from s;
with s as (insert into public.levels (track_slug, level_number, sub_level, kind, skill, title) values ('backend', 14, 1, 'explanation', 'Backend', 'Background Jobs and Queues') on conflict do nothing returning id) insert into public.level_syllabus (level_id, why, steps) select id, 'Slow work like emails and reports should not keep the user waiting.', '["Why Some Work Runs in the Background", "Job Queues and Workers", "Retries and Failed Jobs", "Scheduled Jobs (Cron)"]'::jsonb from s;
with s as (insert into public.levels (track_slug, level_number, sub_level, kind, skill, title) values ('backend', 15, 1, 'explanation', 'System Design', 'Microservices and System Design Basics') on conflict do nothing returning id) insert into public.level_syllabus (level_id, why, steps) select id, 'Interviews and bigger teams expect you to think beyond one server.', '["Monolith vs Microservices", "Load Balancers", "Scaling Reads and Writes", "Designing a URL Shortener", "Explaining a Design in an Interview"]'::jsonb from s;
with s as (insert into public.levels (track_slug, level_number, sub_level, kind, skill, title) values ('backend', 16, 1, 'explanation', 'Docker', 'Shipping a Backend') on conflict do nothing returning id) insert into public.level_syllabus (level_id, why, steps) select id, 'A backend only matters once real users can reach it.', '["Containers with Docker", "Environments: Development, Staging, Production", "CI: Running Tests on Every Change", "Health Checks and Monitoring", "Capstone: A Notes API from Start to Finish"]'::jsonb from s;
insert into public.track_phases (track_slug, phase_number, name, from_level, to_level) values ('backend', 1, 'Foundations', 1, 4) on conflict do nothing;
insert into public.track_phases (track_slug, phase_number, name, from_level, to_level) values ('backend', 2, 'Core Skills', 5, 8) on conflict do nothing;
insert into public.track_phases (track_slug, phase_number, name, from_level, to_level) values ('backend', 3, 'Real Systems', 9, 12) on conflict do nothing;
insert into public.track_phases (track_slug, phase_number, name, from_level, to_level) values ('backend', 4, 'Job Ready', 13, 16) on conflict do nothing;
do $$ begin
  if (select count(*) from public.levels where track_slug = 'backend') <> 16 then raise exception '131: backend should have 16 topics'; end if;
  if (select sum(jsonb_array_length(ls.steps)) from public.level_syllabus ls join public.levels l on l.id = ls.level_id where l.track_slug = 'backend') <> 80 then raise exception '131: step count'; end if;
  if (select count(*) from public.track_phases where track_slug = 'backend') <> 4 then raise exception '131: phases'; end if;
end $$;
commit;
notify pgrst, 'reload schema';
